package dev.vladeezyy.iceandfire.bus;

/** The common @SubscribeEvent methods (generated by tools/port_events.py) */
public final class EventIndex {
    private EventIndex() {
    }

    public static void register() {
        com.github.alexthe666.iceandfire.event.ServerEvents serverEvents = new com.github.alexthe666.iceandfire.event.ServerEvents();
        IafBus.add(AttackEntityEvent.class, EventPriority.NORMAL, serverEvents::onPlayerAttack);
        IafBus.add(AttackEntityEvent.class, EventPriority.NORMAL, serverEvents::onPlayerAttackMob);
        IafBus.add(BlockEvent.BreakEvent.class, EventPriority.NORMAL, serverEvents::onBreakBlock);
        IafBus.add(EntityJoinLevelEvent.class, EventPriority.NORMAL, com.github.alexthe666.iceandfire.entity.props.CapabilityHandler::handleInitialSync);
        IafBus.add(EntityStruckByLightningEvent.class, EventPriority.NORMAL, serverEvents::onLightningHit);
        IafBus.add(VillagerTradesEvent.class, EventPriority.NORMAL, serverEvents::onVillagerTrades);
        IafBus.add(EntityTickEvent.Pre.class, EventPriority.NORMAL, com.github.alexthe666.iceandfire.entity.props.CapabilityHandler::tickData);
        IafBus.add(EntityTickEvent.Pre.class, EventPriority.NORMAL, serverEvents::onEntityUpdate);
        IafBus.add(FMLCommonSetupEvent.class, EventPriority.NORMAL, com.github.alexthe666.iceandfire.recipe.IafRecipeRegistry::preInit);
        IafBus.add(FinalizeSpawnEvent.class, EventPriority.NORMAL, serverEvents::onEntityJoinWorld);
        IafBus.add(LivingChangeTargetEvent.class, EventPriority.NORMAL, serverEvents::onLivingSetTarget);
        IafBus.add(LivingDeathEvent.class, EventPriority.NORMAL, serverEvents::onEntityDie);
        IafBus.add(LivingDropsEvent.class, EventPriority.LOWEST, serverEvents::makeItemDropsFireImmune);
        IafBus.add(LivingDropsEvent.class, EventPriority.NORMAL, serverEvents::onEntityDrop);
        IafBus.add(LivingEntityUseItemEvent.Tick.class, EventPriority.NORMAL, serverEvents::onEntityStopUsingItem);
        IafBus.add(LivingFallEvent.class, EventPriority.NORMAL, serverEvents::onEntityFall);
        IafBus.add(LivingIncomingDamageEvent.class, EventPriority.NORMAL, serverEvents::onEntityDamage);
        IafBus.add(LivingIncomingDamageEvent.class, EventPriority.NORMAL, serverEvents::onLivingAttacked);
        IafBus.add(PlayerEvent.PlayerLoggedOutEvent.class, EventPriority.NORMAL, serverEvents::onPlayerLeaveEvent);
        IafBus.add(PlayerEvent.StartTracking.class, EventPriority.NORMAL, com.github.alexthe666.iceandfire.entity.props.CapabilityHandler::onPlayerStartTracking);
        IafBus.add(PlayerInteractEvent.EntityInteract.class, EventPriority.NORMAL, serverEvents::onEntityInteract);
        IafBus.add(PlayerInteractEvent.LeftClickEmpty.class, EventPriority.NORMAL, serverEvents::onPlayerLeftClick);
        IafBus.add(PlayerInteractEvent.RightClickBlock.class, EventPriority.NORMAL, serverEvents::onPlayerRightClick);
        IafBus.add(PlayerInteractEvent.RightClickItem.class, EventPriority.NORMAL, serverEvents::onEntityUseItem);
        IafBus.add(ProjectileImpactEvent.class, EventPriority.NORMAL, serverEvents::onArrowCollide);
        IafBus.add(ServerAboutToStartEvent.class, EventPriority.NORMAL, serverEvents::addNewVillageBuilding);
    }
}
